interface LogoProps {
  className?: string;
  /** Hide the wordmark and show only the mark. */
  compact?: boolean;
  /** Wraps in a link to the homepage unless false. */
  linked?: boolean;
  markClassName?: string;
  wordmarkClassName?: string;
}

export function Logo({
  className,
  compact,
  linked = true,
  markClassName,
  wordmarkClassName,
}: LogoProps) {
  const content = (
    <span
      className={cn(
        'group/logo inline-flex items-center gap-3 text-foreground',
        className,
      )}
    >
      <LogoMark
        className={cn(
          'transition-transform duration-500 ease-out-expo group-hover/logo:-rotate-6',
          markClassName,
        )}
      />
      {!compact && (
        <Wordmark className={cn('h-[26px] w-auto', wordmarkClassName)} />
      )}
    </span>
  );

  if (!linked) return content;

  return (
    <Link
      href={paths.home}
      aria-label={`${siteConfig.name} home`}
      className='rounded-full focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background'
    >
      {content}
    </Link>
  );
}
